"""Reconstruct M4 generated bytes from a clean archive of committed sources."""
from pathlib import Path
import hashlib
import io
import json
import subprocess
import tarfile
import tempfile

ROOT = Path(__file__).resolve().parents[1]
SOURCE = subprocess.check_output(['git', 'rev-parse', 'HEAD'], cwd=ROOT).decode().strip()
OUTPUTS = [
    'src/maps/siege.mjs', 'assets/fortress/fortress-source.svg',
    'assets/fortress/intact.png', 'assets/fortress/broken.png', 'assets/fortress/half.png',
    'assets/fortress/barrel.svg', 'assets/fortress/gun-cap.svg', 'assets/fortress/anchors.json',
    'preview/guardian.html',
]
STEPS = [
    ['python3', 'tools/export_m4_map.py'],
    ['python3', 'tools/export_fortress.py'],
    ['python3', 'tools/build_preview.py'],
]
with tempfile.TemporaryDirectory(prefix='armorheart-m4-rebuild-', dir='/tmp') as directory:
    clean = Path(directory)
    archive = subprocess.check_output(['git', 'archive', SOURCE], cwd=ROOT)
    with tarfile.open(fileobj=io.BytesIO(archive)) as tar:
        tar.extractall(clean, filter='data')
    for command in STEPS:
        subprocess.run(command, cwd=clean, check=True)
    hashes = {}
    for name in OUTPUTS:
        expected = subprocess.check_output(['git', 'show', SOURCE + ':' + name], cwd=ROOT)
        actual = (clean / name).read_bytes()
        assert actual == expected, 'Non-identical clean reconstruction: ' + name
        hashes[name] = hashlib.sha256(actual).hexdigest()

report = {
    'passed': True, 'source_commit': SOURCE,
    'method': 'git archive into temporary empty directory; regenerate and compare committed output bytes',
    'steps': STEPS, 'byte_identical_sha256': hashes,
    'toolchain': {'chromium': '154.0.8037.57', 'playwright': '1.62.0'},
    'limitations': 'Same installed toolchain/environment; not independent hardware or human artistic acceptance',
}
(ROOT / 'evidence/m4/rebuild-check.json').write_text(json.dumps(report, indent=2) + '\n')
print('Clean M4 reconstruction: all', len(hashes), 'outputs byte-identical; source', SOURCE)
